package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.data.*;import java.io.IOException;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class MoneyState(val loading:Boolean=false,val saving:Boolean=false,val mode:String="accounts",val data:JsonObject=buildJsonObject{},val editing:String?=null,val selected:JsonObject?=null,val error:String?=null)
class AccountMoneyViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(MoneyState());val state:StateFlow<MoneyState> = _state;init{load()};fun show(m:String){_state.value=_state.value.copy(mode=m,editing=null);load()};fun load()=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);try{_state.value=_state.value.copy(loading=false,data=api.moneyContext())}catch(e:Exception){fail(e)}};fun create(kind:String){if(_state.value.saving)return;_state.value=_state.value.copy(editing=kind,selected=null)};fun editOwner(x:JsonObject){if(_state.value.saving)return;_state.value=_state.value.copy(editing="owner-edit",selected=x)};fun editAccount(x:JsonObject){_state.value=_state.value.copy(editing="accounts",selected=x)};fun disableAccount(id:String)=viewModelScope.launch{try{api.disableMoneyAccount(id);load()}catch(e:Exception){fail(e)}};fun loanPayment(x:JsonObject){_state.value=_state.value.copy(editing="loan-payments",selected=x)};fun close(){if(_state.value.saving)return;_state.value=_state.value.copy(editing=null,selected=null)};fun save(kind:String,p:JsonObject)=viewModelScope.launch{if(_state.value.saving)return@launch;_state.value=_state.value.copy(saving=true,error=null);try{if(kind=="owner-edit")api.updateOwnerIdentity(_state.value.selected?.get("id")?.jsonPrimitive?.contentOrNull?:throw IllegalArgumentException("Owner is missing"),p)else if(kind=="accounts")api.saveMoneyAccount(_state.value.selected?.get("id")?.jsonPrimitive?.contentOrNull,p)else api.moneyAction(kind,p);_state.value=_state.value.copy(saving=false);close();load()}catch(e:Exception){fail(e)}};private fun fail(e:Exception){_state.value=_state.value.copy(loading=false,saving=false,error=if(e is IOException)"Offline. No cash/bank change was confirmed." else (e as? ApiException)?.serverMessage?:"Cash/bank action rejected by server.")}}
